#!/usr/bin/env python3
import gzip
import os
import re
import shutil
import subprocess
import sys
from collections import defaultdict


def open_maybe_gzip(path):
    with open(path, "rb") as handle:
        magic = handle.read(2)
    return gzip.open(path, "rt") if magic == b"\x1f\x8b" else open(path, "rt")


def union_length(intervals):
    if not intervals:
        return 0
    merged = []
    for start, end in sorted(intervals):
        if not merged or start > merged[-1][1] + 1:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    return sum(end - start + 1 for start, end in merged)


def flush_query(qid, qlen, rows, summary, details, counters):
    if not qid:
        return
    counters["queries_with_hits"] += 1

    # Collapse duplicate transcript/isoform HSPs to one best HSP per
    # gene and query interval.
    uniq = {}
    for row in rows:
        key = (row["gene"], row["qstart"], row["qend"])
        if key not in uniq or row["bitscore"] > uniq[key]["bitscore"]:
            uniq[key] = row

